\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
WITH n AS (SELECT s.id,s.run_id,s.result,r.outcome,r.report,l.state,l.fence,l.attempt_id,l.lease_until,l.attempt_until FROM reivro_cloud.task_submissions s JOIN reivro_cloud.runs r ON (r.project_id,r.id)=(s.project_id,s.run_id) JOIN reivro_cloud.execution_leases l ON (l.project_id,l.run_id)=(r.project_id,r.id) WHERE s.id=:'new_submission_id'::uuid), old AS (SELECT s.id,s.result,r.outcome,r.report,l.state,l.fence,l.attempt_id FROM reivro_cloud.task_submissions s JOIN reivro_cloud.runs r ON (r.project_id,r.id)=(s.project_id,s.run_id) JOIN reivro_cloud.execution_leases l ON (l.project_id,l.run_id)=(r.project_id,r.id) WHERE s.id IN (:'first_submission_id'::uuid,:'second_submission_id'::uuid,:'third_submission_id'::uuid)), e AS (SELECT count(*) FILTER(WHERE kind='task_renew') renews,count(*) FILTER(WHERE kind='task_fail') fails,count(*) FILTER(WHERE kind='task_finish') finishes,count(*) FILTER(WHERE kind='lease_failure') lease_failures FROM reivro_cloud.events,n WHERE subject IN (n.id,n.run_id)), checks AS (SELECT jsonb_build_object(
 'one_new_task',(SELECT count(*) FROM n)=1,'single_closer',(SELECT fails+finishes=1 FROM e),'renew_at_most_once',(SELECT renews BETWEEN 0 AND 1 FROM e),'fail_shape',(SELECT CASE WHEN fails=1 THEN lease_failures=1 AND n.state='retryable' AND n.result IS NULL AND n.outcome IS NULL AND n.report IS NULL ELSE lease_failures=0 END FROM e,n),'finish_shape',(SELECT CASE WHEN finishes=1 THEN n.state='completed' AND n.result->>'status'='VERIFIED' AND n.outcome='INCONCLUSIVE' AND n.report=n.result ELSE true END FROM e,n),'closed_attempt',(SELECT attempt_id IS NULL AND lease_until IS NULL AND attempt_until IS NULL AND fence=1 FROM n),'journal_allowed',(SELECT count(*)=(47+(SELECT renews+finishes+2*fails FROM e)) AND count(*) BETWEEN 48 AND 50 AND max(seq)=count(*) FROM reivro_cloud.events),'sequence_matches',(SELECT last_value=(SELECT count(*) FROM reivro_cloud.events) AND is_called FROM reivro_cloud.events_seq_seq),'first_preserved',(SELECT count(*)=1 FROM old WHERE id=:'first_submission_id'::uuid AND state='completed' AND fence=3 AND attempt_id IS NULL AND result->>'status'='VERIFIED' AND outcome='INCONCLUSIVE' AND report=result),'second_preserved',(SELECT count(*)=1 FROM old WHERE id=:'second_submission_id'::uuid AND state='terminal' AND fence=3 AND attempt_id IS NULL AND result IS NULL AND outcome='ERROR' AND report IS NULL),'third_preserved',(SELECT count(*)=1 FROM old WHERE id=:'third_submission_id'::uuid AND state='running' AND fence=1 AND attempt_id IS NOT NULL AND result IS NULL AND outcome IS NULL AND report IS NULL),'inventory',(SELECT count(*)=4 FROM reivro_cloud.task_contracts) AND (SELECT count(*)=4 FROM reivro_cloud.task_submissions) AND (SELECT count(*)=4 FROM reivro_cloud.runs WHERE task_submission_id IS NOT NULL) AND (SELECT count(*)=4 FROM reivro_cloud.execution_leases),'no_prepared_xacts',(SELECT count(*)=0 FROM pg_prepared_xacts)) value FROM e)
SELECT jsonb_build_object('checks',value,'all_checks_pass',NOT EXISTS(SELECT FROM jsonb_each(value)e WHERE e.value IS DISTINCT FROM 'true'::jsonb),'journal',(SELECT count(*) FROM reivro_cloud.events),'state',(SELECT state FROM n),'renews',(SELECT renews FROM e),'fails',(SELECT fails FROM e),'finishes',(SELECT finishes FROM e)) FROM checks;
COMMIT;
